def standard():
    x = symbols('x')
    y = lambda v: 2*cos(pi*v/6)
    A = (4, y(4)); B = (6, y(6))
    tot = 0
    import numpy
    xs = numpy.linspace(0.001, 17.999, 180000)
    cands = set()
    for P0 in (A, B):
        # line through P0 and (9,0)
        m = (0 - P0[1])/(9 - P0[0])
        g = lambda v: 2*numpy.cos(numpy.pi*v/6) - float(m)*(v - 9)
        vals = g(xs)
        for i in range(len(xs) - 1):
            if vals[i] == 0 or vals[i]*vals[i + 1] < 0:
                r = nsolve(2*cos(pi*x/6) - m*(x - 9), x, xs[i])
                if r > 9 - 1e-9:
                    cands.add(round(float(r), 9))
    cands.add(9.0)
    for cx in cands:
        cxs = nsimplify(cx)
        tot += (4 + 6 + cxs + A[1] + B[1] + y(cxs))/3
    return nsimplify(tot)

