def standard():
    x, t, r, c = symbols('x t r c', real=True)
    f = -c*(x - r)*(x - 6)
    F = integrate(f.subs(x, t), (t, 0, x))
    rv = solve(F.subs(x, 3), r)
    res = set()
    for rr in rv:
        for cc in solve(Eq(Abs(f.subs({r: rr, x: 0})), 2), c):
            if cc <= 0: continue
            ff = f.subs({r: rr, c: cc}); FF = F.subs({r: rr, c: cc})
            pts = [Rational(k, 20) for k in range(-100, 200)]
            S = [p for p in pts if ff.subs(x, p) > 0 and FF.subs(x, p) > 0]
            if S and min(S) > 3 and max(S) < 6 and min(S) <= 3 + Rational(1, 20) and max(S) >= 6 - Rational(1, 20):
                res.add(ff.subs(x, 3))
    assert len(res) == 1
    return res.pop()

