def standard():
    x, t = symbols('x t', real=True)
    res = set()
    for a in [Rational(k, 4) for k in range(-40, 41) if k != 0]:
        fl = -x**3 - a*x; fr = a*x**2 - a*x
        Fl = integrate(fl, (x, 0, t)); Fr = integrate(fr, (x, 0, t))
        # candidates for max of F: critical points
        crit = [0, 1] + [r for r in solve(fl, x) if r.is_real and r < 0]
        vals = [Fl.subs(t, r) if r < 0 else Fr.subs(t, r) for r in crit]
        # F unbounded above?
        if limit(Fr, t, oo) == oo or limit(Fl, t, -oo) == oo:
            continue
        M = max(vals)
        # positive s with f(s) >= M
        fmax = fr.subs(x, Rational(1, 2)) if a < 0 else None
        if fmax is not None and fmax == M:
            res.add(fl.subs(x, -4))
    assert len(res) == 1
    return res.pop()

