def standard():
    x, p = symbols('x p', real=True)
    q = -Rational(1, 4) - 5*p
    g = (x - 1)**2*(p*x + q)
    x0 = solve(p*x + q, x)[0]
    pv = [v for v in solve(Eq(1 + x0, 8), p) if v > 0][0]
    G = g.subs(p, pv)
    # numeric check: count nondiff points of |f - f(k)| for sample k, expecting only k in {1, 7}
    fL = diff(G, x); fR = G
    f = lambda v: fL.subs(x, v) if v < 1 else fR.subs(x, v)
    assert f(1) == 0 and f(7) == 0
    return fL.subs(x, -3)

